// Energy display is a cosmetic intimidation action, independent of combat buffs.
export function pressureProfile(rank){const r=Math.max(0,Math.min(100,Math.floor(Number(rank)||0))),stage=Math.min(5,Math.floor(r/20));return {rank:r,stage,radius:48+r*1.05,height:110+r*1.25,particles:r?12+Math.floor(r*.6):0,rings:1+stage,duration:3.2,cooldown:20};}
export function releasePressure(state,player,now){const profile=pressureProfile(player?.magicula?.rank);if(!profile.rank)return {ok:false,reason:'Desperte as Magículas para liberar sua presença.'};if(!Number.isFinite(now))return {ok:false,reason:'Tempo inválido.'};const remaining=Math.max(0,(state.pressureReadyAt||0)-now);if(remaining>0)return {ok:false,reason:'Presença em recarga: '+Math.ceil(remaining)+'s.'};state.pressureStartedAt=now;state.pressureReadyAt=now+profile.cooldown;state.pressureRank=profile.rank;return {ok:true,profile};}
